response:
The crash is from the C matrix indexing. In Fortran, `C` is a 72-element array (4 blocks of 18), and `C(J+1)` etc. with `J=18*I-18`. But I made an error: I'm writing to `C(0,0)` repeatedly in the loop, overwriting. The Fortran code fills 4 separate 6x3 blocks (one per node I), stored at offsets 18*I-18.

Let me re-read: `C(J+1)=H(I+4)` where `J=18*I-18`. So for I=1, J=0, C(1)=H(5). For I=2, J=18, C(19)=H(6). Each block is 18 elements = 6x3. So C is 4 separate 6x3 matrices, one per node.

Then `C(NPOINT)` with `NPOINT=18*I-35` picks the block for the pivot node. And `C(18*I-17)` picks block for node I.

So I need 4 separate C matrices. Let me fix.

[TOOL: compile_and_run]

```cpp
#include <Eigen/Dense>
#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace Eigen;

static const int M[12][4] = {
    {1,2,3,4},{1,2,3,5},{1,2,3,6},{1,4,5,6},
    {2,4,5,6},{3,4,5,6},{2,1,4,6},{2,3,4,6},
    {1,3,4,5},{2,3,4,5},{3,1,5,6},{2,1,5,6}
};

int main() {
    double coords[6][3] = {
        {0,0,0},{1,0,0},{0,1,0},{0,0,1},{1,0,1},{0,1,1}
    };
    double E = 200e9;
    double nu = 0.3;
    double GG = E / (2.0*(1.0+nu));

    Matrix<double,6,6> G = Matrix<double,6,6>::Zero();
    double TEMP1 = (1.0+nu)*(1.0-2.0*nu);
    double g1 = E*(1.0-nu)/TEMP1;
    double g2 = E*nu/TEMP1;
    G(0,0)=g1; G(1,1)=g1; G(2,2)=g1;
    G(0,1)=g2; G(0,2)=g2;
    G(1,0)=g2; G(1,2)=g2;
    G(2,0)=g2; G(2,1)=g2;
    G(3,3)=GG; G(4,4)=GG; G(5,5)=GG;

    Matrix<double,18,18> K = Matrix<double,18,18>::Zero();

    for (int itet = 0; itet < 12; itet++) {
        int nodes[4];
        for (int j = 0; j < 4; j++) nodes[j] = M[itet][j] - 1;

        Matrix4d H;
        for (int i = 0; i < 4; i++) {
            H(i,0) = 1.0;
            H(i,1) = coords[nodes[i]][0];
            H(i,2) = coords[nodes[i]][1];
            H(i,3) = coords[nodes[i]][2];
        }

        double det = H.determinant();
        if (std::abs(det) < 1e-300) continue;
        Matrix4d Hinv = H.inverse();
        double HDETER = std::abs(det);

        // 4 separate 6x3 C matrices, one per node I
        Matrix<double,6,3> Cmat[4];
        for (int I = 0; I < 4; I++) {
            Cmat[I] = Matrix<double,6,3>::Zero();
            double h_i4  = Hinv(I,1);
            double h_i8  = Hinv(I,2);
            double h_i12 = Hinv(I,3);
            // Fortran: C(J+1)=H(I+4), C(J+5)=H(I+8), C(J+9)=H(I+12),
            //          C(J+11)=H(I+12), C(J+12)=H(I+8), C(J+13)=H(I+12),
            //          C(J+15)=H(I+4), C(J+16)=H(I+8), C(J+17)=H(I+4)
            // 1-based within block -> 0-based
            Cmat[I](0,0) = h_i4;
            Cmat[I](4,0) = h_i8;
            Cmat[I](8,0) = h_i12;
            Cmat[I](10,0) = h_i12;
            Cmat[I](11,0) = h_i8;
            Cmat[I](12,0) = h_i12;
            Cmat[I](14,0) = h_i4;
            Cmat[I](15,0) = h_i8;
            Cmat[I](16,0) = h_i4;
        }

        int IOPT = itet + 11;
        HDETER = HDETER / 36.0;
        if (IOPT <= 16) HDETER = HDETER * 2.0;

        // Pivot point: find which node is NPVT. In KSOLID, NPVT is the pivot.
        // For our standalone test, we assemble all contributions.
        // GCT = C_pivot^T * G, then KIJ = GCT * C_I for each node I.
        // But pivot is one specific node. We need to know NPVT.
        // In the full assembly, each tetra contributes to pivot row/col.
        // For a standalone full stiffness, we sum over all pivot choices.
        // Actually KTETRA inserts KIJ for pivot vs each of 4 nodes.
        // The full element stiffness is assembled by SMA1B over all tetras.
        // For our test, we assume pivot = node 1 of the tetra (NPVT matches).
        // Let's use pivot = nodes[0] (first node of tetra).
        int pivot = 0; // index into Cmat
        Matrix<double,3,6> GCT = Cmat[pivot].transpose() * G;
        GCT = GCT * HDETER;

        for (int I = 0; I < 4; I++) {
            Matrix3d T = GCT * Cmat[I];
            int node = nodes[I];
            int base = 3*node;
            for (int a = 0; a < 3; a++)
                for (int b = 0; b < 3; b++)
                    K(base+a, base+b) += T(a,b);
        }
    }

    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 18; i++) {
        std::cout << "[";
        for (int j = 0; j < 18; j++) {
            std::cout << std::scientific << std::setprecision(6) << K(i,j);
            if (j < 17) std::cout << ",";
        }
        std::cout << "]";
        if (i < 17) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
